package org.okulos.bench;

import ai.timefold.solver.core.api.domain.common.PlanningId;
import ai.timefold.solver.core.api.domain.entity.PlanningEntity;
import ai.timefold.solver.core.api.domain.solution.PlanningEntityCollectionProperty;
import ai.timefold.solver.core.api.domain.solution.PlanningScore;
import ai.timefold.solver.core.api.domain.solution.PlanningSolution;
import ai.timefold.solver.core.api.domain.solution.ProblemFactCollectionProperty;
import ai.timefold.solver.core.api.domain.valuerange.ValueRangeProvider;
import ai.timefold.solver.core.api.domain.variable.PlanningVariable;
import ai.timefold.solver.core.api.score.HardSoftScore;
import ai.timefold.solver.core.api.score.calculator.EasyScoreCalculator;
import ai.timefold.solver.core.api.solver.Solver;
import ai.timefold.solver.core.api.solver.SolverFactory;
import ai.timefold.solver.core.config.solver.SolverConfig;
import ai.timefold.solver.core.config.solver.termination.TerminationConfig;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;

public final class TimefoldWorldBenchmark {
  static final ObjectMapper M=new ObjectMapper();
  public static final class Slot{public int day,period;public Slot(){}public Slot(int d,int p){day=d;period=p;}public int getDay(){return day;}public int getPeriod(){return period;}public boolean equals(Object o){return o instanceof Slot s&&s.day==day&&s.period==period;}public int hashCode(){return Objects.hash(day,period);}}
  public static final class TeacherLimit{public String teacherId;public Integer maxDailyHours,maxConsecutiveHours;public TeacherLimit(){}public TeacherLimit(String t,Integer d,Integer c){teacherId=t;maxDailyHours=d;maxConsecutiveHours=c;}}
  @PlanningEntity public static final class Lesson{@PlanningId public String id;public String teacherId,classId,weekPattern;public Set<Integer> allowedPeriods;@PlanningVariable(valueRangeProviderRefs="slotRange") public Slot slot;public Lesson(){}public Lesson(String i,String t,String c,String w,Set<Integer>a){id=i;teacherId=t;classId=c;weekPattern=w==null?"ALL":w;allowedPeriods=a==null?Set.of():a;}}
  @PlanningSolution public static final class Timetable{@ProblemFactCollectionProperty @ValueRangeProvider(id="slotRange") public List<Slot> slots;@ProblemFactCollectionProperty public List<TeacherLimit> limits;@PlanningEntityCollectionProperty public List<Lesson> lessons;@PlanningScore public HardSoftScore score;public Timetable(){}public Timetable(List<Slot>s,List<TeacherLimit>l,List<Lesson>x){slots=s;limits=l;lessons=x;}}
  public static final class ScoreCalc implements EasyScoreCalculator<Timetable,HardSoftScore>{static boolean overlap(String a,String b){return !("ODD".equals(a)&&"EVEN".equals(b)||"EVEN".equals(a)&&"ODD".equals(b));}public HardSoftScore calculateScore(Timetable t){int hard=0;var ls=t.lessons;for(var l:ls)if(l.slot!=null&&!l.allowedPeriods.isEmpty()&&!l.allowedPeriods.contains(l.slot.period))hard++;for(int i=0;i<ls.size();i++){var a=ls.get(i);if(a.slot==null)continue;for(int j=i+1;j<ls.size();j++){var b=ls.get(j);if(b.slot==null||!a.slot.equals(b.slot)||!overlap(a.weekPattern,b.weekPattern))continue;if(a.teacherId.equals(b.teacherId)||a.classId.equals(b.classId))hard++;}}for(var lim:t.limits)for(int day:t.slots.stream().map(s->s.day).distinct().toList())for(String ctx:List.of("ODD","EVEN")){var ps=new ArrayList<Integer>();for(var l:ls)if(l.slot!=null&&l.slot.day==day&&l.teacherId.equals(lim.teacherId)&&!(("ODD".equals(ctx)&&"EVEN".equals(l.weekPattern))||("EVEN".equals(ctx)&&"ODD".equals(l.weekPattern))))ps.add(l.slot.period);if(lim.maxDailyHours!=null&&ps.size()>lim.maxDailyHours)hard+=ps.size()-lim.maxDailyHours;if(lim.maxConsecutiveHours!=null){var set=new HashSet<>(ps);int run=0,best=0,max=t.slots.stream().mapToInt(s->s.period).max().orElse(0);for(int p=1;p<=max;p++){run=set.contains(p)?run+1:0;best=Math.max(best,run);}if(best>lim.maxConsecutiveHours)hard+=best-lim.maxConsecutiveHours;}}return HardSoftScore.of(-hard,0);}}
  static Timetable problem(JsonNode c){JsonNode p=c.get("problem");var slots=new ArrayList<Slot>();for(var d:p.get("days"))for(int h=1;h<=p.get("periods").asInt();h++)slots.add(new Slot(d.asInt(),h));var limits=new ArrayList<TeacherLimit>();for(var x:p.get("teacherConstraints"))limits.add(new TeacherLimit(x.get("teacher_id").asText(),nullableInt(x.get("max_daily_hours")),nullableInt(x.get("max_consecutive_hours"))));var lessons=new ArrayList<Lesson>();for(var a:p.get("assignments")){var allowed=new LinkedHashSet<Integer>();if(a.has("allowed_periods")&&a.get("allowed_periods").isArray())for(var h:a.get("allowed_periods"))allowed.add(h.asInt());lessons.add(new Lesson(a.get("assignment_id").asText(),a.get("teacher_id").asText(),a.get("class_id").asText(),a.hasNonNull("week_pattern")?a.get("week_pattern").asText():"ALL",allowed));}return new Timetable(slots,limits,lessons);}
  static Integer nullableInt(JsonNode n){return n==null||n.isNull()?null:n.asInt();}
  static String sig(Timetable t){var a=new ArrayList<String>();for(var l:t.lessons)a.add(l.id+"@"+(l.slot==null?"null":l.slot.day+":"+l.slot.period));Collections.sort(a);return String.join("|",a);}
  static Timetable solve(JsonNode c){long seed=c.get("seed").asLong(),budget=c.get("wall_clock_budget_ms").asLong();var term=new TerminationConfig().withSpentLimit(Duration.ofMillis(budget)).withBestScoreFeasible(true);var cfg=new SolverConfig().withSolutionClass(Timetable.class).withEntityClasses(Lesson.class).withEasyScoreCalculatorClass(ScoreCalc.class).withRandomSeed(seed).withTerminationConfig(term);Solver<Timetable>s=SolverFactory.<Timetable>create(cfg).buildSolver();return s.solve(problem(c));}
  static ObjectNode run(JsonNode c,boolean replay){long mem0=used(),t0=System.nanoTime();Timetable r;try{r=solve(c);}catch(Exception e){var z=M.createObjectNode();z.put("solver_id","timefold");z.put("input_hash",c.get("input_hash").asText());z.put("profile_id",c.get("profile_id").asText());z.put("seed",c.get("seed").asLong());z.put("status","ERROR");z.put("feasible",false);z.set("diagnostics",M.createObjectNode().put("error",e.toString()));return z;}long ms=Math.round((System.nanoTime()-t0)/1_000_000.0),hard=-r.score.hardScore();int unplaced=(int)r.lessons.stream().filter(l->l.slot==null).count();boolean feasible=unplaced==0&&hard==0;var z=M.createObjectNode();z.put("solver_id","timefold");z.put("solver_version","2.5.0");z.put("mapping","HARD_COMMON_CORE");z.put("comparable_objective",false);z.put("input_hash",c.get("input_hash").asText());z.put("profile_id",c.get("profile_id").asText());z.put("seed",c.get("seed").asLong());z.put("status",ms>c.get("wall_clock_budget_ms").asLong()+1500?"TIMEOUT":"COMPLETED");z.put("feasible",feasible);z.put("hard",hard);z.put("unplaced",unplaced);z.put("runtime_ms",ms);z.put("time_to_first_feasible_ms",feasible?ms:-1);z.put("time_to_best_ms",ms);z.put("peak_memory_mb",Math.max(0,(used()-mem0)/1048576));var rows=M.createArrayNode();for(var l:r.lessons)if(l.slot!=null){var q=M.createObjectNode();q.put("assignment_id",l.id);q.put("weekday",l.slot.day);q.put("period",l.slot.period);rows.add(q);}z.set("rows",rows);if(replay){var r2=solve(c);z.put("deterministic_replay",sig(r).equals(sig(r2))&&r.score.equals(r2.score));}return z;}
  static long used(){var x=Runtime.getRuntime();return x.totalMemory()-x.freeMemory();}
  public static void main(String[] args)throws Exception{if(args.length<2)throw new IllegalArgumentException("usage: <cases.ndjson> <out.ndjson>");try(var in=Files.lines(Path.of(args[0]));var out=Files.newBufferedWriter(Path.of(args[1]))){var first=new HashSet<String>();for(var it=in.iterator();it.hasNext();){var c=M.readTree(it.next());boolean replay=first.add(c.get("profile_id").asText());out.write(M.writeValueAsString(run(c,replay)));out.newLine();out.flush();}}}
}
